"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Check } from "lucide-react";
import { PLANS } from "@/lib/plans";
import { Button } from "@/components/ui/button";
import { DateTime } from "@/components/date-time";
import { refreshWorkspaceAccess } from "@/components/workspace-quota";
import type { ClientBillingStatus } from "@/lib/billing/status";
import {
  BILLING_PRICES,
  PRICE_TAX_DESCRIPTION,
  SUPPORT_EMAIL,
} from "@/lib/pricing";

type Confirmation = "confirming" | "confirmed" | "failed" | "expired";
function confirmationFor(billing: ClientBillingStatus): Confirmation {
  if (billing.checkoutState === "FAILED") return "failed";
  if (billing.checkoutState === "EXPIRED") return "expired";
  if (billing.checkoutState && billing.checkoutState !== "COMPLETED")
    return "confirming";
  const now = Date.now();
  const end =
    billing.status === "PAST_DUE" ? billing.gracePeriodEnd : billing.periodEnd;
  // An effective Paid override alone is never evidence of a settled subscription.
  if (
    billing.paymentConfirmed &&
    ["ACTIVE", "PAST_DUE"].includes(billing.status) &&
    billing.periodStart &&
    new Date(billing.periodStart).getTime() <= now &&
    end &&
    now < new Date(end).getTime()
  )
    return "confirmed";
  if (billing.status === "FAILED") return "failed";
  if (billing.status === "EXPIRED") return "expired";
  return "confirming";
}

export type BillingControlsPresentation = {
  billing: ClientBillingStatus | null;
  busy: boolean;
  message: string;
  lookupFailed: boolean;
  pending: boolean;
  hasSubscription: boolean;
  recurring: string;
  publicPrice: string;
  canUpgrade: boolean;
  canCancel: boolean;
  canManage: boolean;
  open: (kind: "checkout" | "portal" | "cancel") => Promise<void>;
  refresh: () => Promise<void>;
};

export function BillingControls({
  returning = false,
  initialBilling = null,
  advertisedPrice,
  renderContent,
}: {
  renderContent?: (controls: BillingControlsPresentation) => ReactNode;
  returning?: boolean;
  advertisedPrice: { symbol: string; amount: number };
  initialBilling?: ClientBillingStatus | null;
}) {
  const router = useRouter();
  const [billing, setBilling] = useState(initialBilling);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [lookupFailed, setLookupFailed] = useState(false);
  const [pollingEnded, setPollingEnded] = useState(false);
  const [confirmation, setConfirmation] = useState<Confirmation>("confirming");
  const attemptKey = useRef<string | null>(null);
  const manualRefresh = useRef<() => Promise<void>>(async () => {});
  const accessRefreshed = useRef(false);

  useEffect(() => {
    let active = true,
      pending = false,
      stopped = false;
    const controller = new AbortController();
    const deadlineAt = Date.now() + 120_000;
    async function refresh() {
      if (pending || !active) return;
      pending = true;
      try {
        const response = await fetch("/api/billing/status", {
          cache: "no-store",
          signal: AbortSignal.any([
            controller.signal,
            AbortSignal.timeout(10_000),
          ]),
        });
        if (!response.ok) throw new Error();
        const result: ClientBillingStatus = await response.json();
        if (!active) return;
        setBilling(result);
        setLookupFailed(false);
        if (result.cancelAtPeriodEnd && !result.cancellationPending)
          setMessage((current) =>
            current === "Cancellation requested. Waiting for confirmation."
              ? ""
              : current,
          );
        if (returning) {
          const outcome = confirmationFor(result);
          setConfirmation(outcome);
          if (outcome !== "confirming") stopped = true;
          if (outcome === "confirmed" && !accessRefreshed.current) {
            accessRefreshed.current = true;
            refreshWorkspaceAccess();
            router.refresh();
          }
        }
      } catch {
        if (active) setLookupFailed(true);
      } finally {
        pending = false;
      }
    }
    manualRefresh.current = refresh;
    const initial = window.setTimeout(() => void refresh(), 0);
    const onVisible = () => {
      if (stopped) return;
      // Wall time also guards focus after browsers throttle background timers.
      if (returning && Date.now() >= deadlineAt) {
        stopped = true;
        setPollingEnded(true);
        return;
      }
      if (document.visibilityState === "visible") void refresh();
    };
    const interval = window.setInterval(onVisible, returning ? 5000 : 60_000);
    const deadline = returning
      ? window.setTimeout(() => {
          if (!stopped) {
            stopped = true;
            setPollingEnded(true);
          }
          window.clearInterval(interval);
        }, 120_000)
      : undefined;
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("focus", onVisible);
    return () => {
      active = false;
      controller.abort();
      window.clearTimeout(initial);
      window.clearTimeout(deadline);
      window.clearInterval(interval);
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("focus", onVisible);
    };
  }, [returning, router]);

  async function open(kind: "checkout" | "portal" | "cancel") {
    setBusy(true);
    setMessage("");
    try {
      attemptKey.current ??= crypto.randomUUID();
      const response = await fetch(`/api/billing/${kind}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body:
          kind === "checkout"
            ? JSON.stringify({
                plan: "paid_monthly",
                idempotencyKey: attemptKey.current,
              })
            : "{}",
      });
      const result = await response.json();
      if (!response.ok) {
        if (result.code === "CHECKOUT_ATTEMPT_FINISHED")
          attemptKey.current = null;
        throw new Error(
          result.error || "Could not open subscription controls.",
        );
      }
      if (kind === "cancel") {
        setBilling((current) =>
          current
            ? {
                ...current,
                cancellationPending: Boolean(result.cancellationPending),
              }
            : current,
        );
        setMessage("Cancellation requested. Waiting for confirmation.");
        setBusy(false);
        await manualRefresh.current();
        return;
      }
      window.location.assign(
        kind === "checkout" ? result.checkoutUrl : result.portalUrl,
      );
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Could not open subscription controls.",
      );
      setBusy(false);
      void manualRefresh.current();
    }
  }
  const pending =
    billing?.status === "PENDING" ||
    Boolean(
      billing?.checkoutState &&
      !["READY", "COMPLETED", "FAILED", "EXPIRED"].includes(
        billing.checkoutState,
      ),
    );
  const hasSubscription =
    billing &&
    !["NONE", "CANCELLED", "EXPIRED", "FAILED"].includes(billing.status);
  const publicPrice =
    billing?.billingCountry === "IN"
      ? `₹${BILLING_PRICES.INR / 100}/month`
      : billing?.billingCountry
        ? `US$${BILLING_PRICES.USD / 100}/month`
        : `${advertisedPrice.symbol}${advertisedPrice.amount}/month`;
  const amount = billing?.recurringAmountMinor;
  const currency = billing?.recurringCurrency;
  // Never infer a subscription charge from billing country or advertised prices.
  let recurring = "Unavailable";
  if (amount !== null && amount !== undefined && currency) {
    try {
      recurring =
        new Intl.NumberFormat(undefined, {
          style: "currency",
          currency,
        }).format(amount / 100) + ` ${currency}/month`;
    } catch {
      /* Unknown currency stays unavailable. */
    }
  }
  async function refreshStatus() {
    await manualRefresh.current();
  }
  if (renderContent && !returning) {
    // The presentation wires these handlers to events; it never invokes them during render.
    // eslint-disable-next-line react-hooks/refs
    return renderContent({
      billing,
      busy,
      message,
      lookupFailed,
      pending,
      hasSubscription: Boolean(hasSubscription),
      recurring,
      publicPrice,
      canUpgrade: Boolean(
        billing?.configured &&
        !billing.isSuspended &&
        !hasSubscription &&
        !pending,
      ),
      canCancel: Boolean(
        billing?.configured && hasSubscription && !billing.cancelAtPeriodEnd,
      ),
      canManage: Boolean(billing?.configured && billing.hasCustomer),
      open,
      refresh: refreshStatus,
    });
  }
  if (returning && confirmation === "confirmed" && billing) {
    const premiumAccess = !billing.isSuspended && billing.plan === "PAID";
    const renewal =
      billing.status === "PAST_DUE" && !billing.cancelAtPeriodEnd
        ? billing.gracePeriodEnd
        : billing.periodEnd;
    return (
      <section
        aria-label="Subscription"
        data-checkout-confirmed
        className="rounded-[28px] border border-[var(--confirmation-border)] bg-[var(--confirmation-card)] p-5 sm:rounded-[36px] sm:p-12"
      >
        <div className="space-y-8 sm:space-y-9">
          <div
            role="status"
            aria-live="polite"
            className="flex flex-col items-start gap-7 sm:flex-row"
          >
            <div className="flex size-[84px] shrink-0 items-center justify-center rounded-[24px] bg-[var(--confirmation-accent-soft)]">
              <span className="flex size-[45px] items-center justify-center rounded-full bg-[var(--confirmation-accent)] text-[var(--confirmation-ink)]">
                <Check className="size-7" strokeWidth={3} aria-hidden="true" />
              </span>
            </div>
            <div className="min-w-0 space-y-4">
              <div className="flex flex-wrap gap-3 text-base font-semibold leading-5">
                <span className="rounded-full bg-[var(--confirmation-accent)] px-4 py-2 text-[var(--confirmation-ink)]">
                  PREMIUM
                </span>
                {billing.mode === "test" && (
                  <span className="rounded-full border border-[var(--confirmation-border)] px-4 py-2 text-[var(--confirmation-muted)]">
                    TEST MODE
                  </span>
                )}
              </div>
              <h2 className="text-[32px] font-semibold leading-[1.2] tracking-[-0.03em] [font-family:inherit] sm:text-[40px]">
                {premiumAccess ? "You’re on Premium" : "Payment confirmed"}
              </h2>
              <p className="max-w-[650px] text-lg leading-[1.6] [text-wrap:wrap] text-[var(--confirmation-muted)] sm:text-[21px]">
                {premiumAccess && billing.status === "ACTIVE"
                  ? "Payment verified and your subscription is active. Your new limits are live."
                  : "Your payment is confirmed. Your current subscription and account access are shown below."}
              </p>
            </div>
          </div>

          <dl className="grid gap-[18px] md:grid-cols-3">
            <div className="min-w-0 space-y-3 rounded-[24px] border border-[var(--confirmation-border)] bg-[var(--confirmation-tile)] p-6">
              <dt className="text-base text-[var(--confirmation-muted)]">
                Plan price
              </dt>
              <dd className="space-y-3">
                <p className="text-[30px] font-semibold leading-9 tracking-tight">
                  {publicPrice}
                </p>
                <p className="text-base leading-6 text-[var(--confirmation-muted)]">
                  Includes applicable tax
                </p>
              </dd>
            </div>
            <div className="min-w-0 space-y-3 rounded-[24px] border border-[var(--confirmation-border)] bg-[var(--confirmation-tile)] p-6">
              <dt className="text-base text-[var(--confirmation-muted)]">
                {billing.cancelAtPeriodEnd
                  ? "Paid period ends"
                  : billing.status === "PAST_DUE"
                    ? "Grace period ends"
                    : "Next renewal"}
              </dt>
              <dd className="space-y-3">
                <p className="text-[30px] font-semibold leading-9 tracking-tight">
                  <DateTime value={renewal} format="date" />
                </p>
                <p className="text-base leading-6 text-[var(--confirmation-muted)]">
                  <DateTime value={renewal} format="time" />
                </p>
              </dd>
            </div>
            <div className="min-w-0 space-y-3 rounded-[24px] border border-[var(--confirmation-border)] bg-[var(--confirmation-tile)] p-6">
              <dt className="text-base text-[var(--confirmation-muted)]">
                Status
              </dt>
              <dd className="space-y-3">
                <p className="flex items-center gap-3 text-[30px] font-semibold leading-9 capitalize">
                  <span
                    data-subscription-status-dot
                    aria-hidden="true"
                    className={
                      billing.status === "ACTIVE"
                        ? "size-3 shrink-0 rounded-full bg-success"
                        : "size-3 shrink-0 rounded-full bg-warning"
                    }
                  />
                  {billing.status.toLowerCase().replaceAll("_", " ")}
                </p>
                <p className="text-base leading-6 text-[var(--confirmation-muted)]">
                  Access:{" "}
                  {billing.isSuspended
                    ? "Suspended"
                    : premiumAccess
                      ? "Paid"
                      : "Free"}
                </p>
              </dd>
            </div>
          </dl>

          <div className="flex flex-wrap items-center gap-x-9 gap-y-3">
            {[
              { value: PLANS.PAID.dailyEmails, label: "emails per day" },
              { value: PLANS.PAID.monthlyEmails, label: "emails per month" },
            ].map(({ value, label }) => (
              <p
                key={label}
                className="flex items-center gap-[14px] text-lg text-[var(--confirmation-muted)] sm:text-xl"
              >
                <span className="flex size-[30px] shrink-0 items-center justify-center rounded-full bg-[var(--confirmation-accent)] text-[var(--confirmation-ink)]">
                  <Check
                    className="size-[18px]"
                    strokeWidth={3}
                    aria-hidden="true"
                  />
                </span>
                <span>
                  <strong className="text-[var(--confirmation-text)]">
                    {value}
                  </strong>{" "}
                  {label}
                </span>
              </p>
            ))}
            <Link
              href="/pricing"
              className="ml-auto inline-flex min-h-9 items-center text-lg text-[var(--confirmation-accent-text)] hover:underline"
            >
              Compare plan allowances
            </Link>
          </div>

          <div className="space-y-3 text-sm leading-6 text-[var(--confirmation-muted)] empty:hidden">
            {billing.isSuspended && (
              <p className="text-warning">
                Sending and paid features are suspended. Suspension does not
                cancel billing. You can manage or cancel your subscription on
                Settings.
              </p>
            )}
            {billing.hasOverride && (
              <p>
                An active access override or grant affects your access
                separately from your subscription.
              </p>
            )}
            {billing.cancellationPending && (
              <p role="status">
                Cancellation requested. Waiting for confirmation; your verified
                paid period is retained.
              </p>
            )}
            {billing.cancelAtPeriodEnd && billing.periodEnd && (
              <p>
                Cancellation scheduled. Verified paid access ends{" "}
                <DateTime value={billing.periodEnd} />.
              </p>
            )}
            {billing.status === "PAST_DUE" && billing.gracePeriodEnd && (
              <p className="text-warning">
                Renewal payment needs attention. The verified grace period ends{" "}
                <DateTime value={billing.gracePeriodEnd} />.
              </p>
            )}
            {!billing.configured ? (
              <p>
                Checkout is not configured yet. Subscription controls are
                unavailable until configuration is restored; stored subscription
                details remain visible.
              </p>
            ) : (
              !billing.checkoutEnabled && <p>Checkout is currently disabled.</p>
            )}
          </div>

          <div
            className="flex flex-wrap items-center gap-4"
            aria-label="Subscription actions"
          >
            <Button
              asChild
              className="h-auto min-h-[68px] max-w-full whitespace-normal rounded-[18px] [background:var(--confirmation-accent)] px-7 py-4 text-xl font-semibold text-[var(--confirmation-ink)]"
            >
              <Link href="/usage">Back to Usage</Link>
            </Button>
          </div>
        </div>

        <div className="mt-9 flex flex-wrap items-end justify-between gap-x-6 gap-y-4 border-t border-dotted border-separator pt-7">
          <p className="max-w-[570px] text-base leading-7 text-[var(--confirmation-muted)]">
            Recurring amount before tax: {recurring}. Invoices show applicable
            tax.{" "}
            {billing?.mode === "test" &&
              "Test mode — no real charges are made."}
          </p>
          <div className="flex flex-wrap items-center gap-1 text-lg text-[var(--confirmation-accent-text)]">
            <button
              type="button"
              className="min-h-11 hover:underline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring"
              onClick={() => void refreshStatus()}
            >
              Refresh status
            </button>
            <span aria-hidden="true">·</span>
            <a
              href={`mailto:${SUPPORT_EMAIL}`}
              className="inline-flex min-h-11 items-center hover:underline"
            >
              Contact support
            </a>
          </div>
          {lookupFailed && (
            <p className="w-full text-sm text-warning" role="alert">
              Subscription status lookup temporarily failed. Your last verified
              status is retained. Try refreshing shortly.
            </p>
          )}
          {message && (
            <p className="w-full text-sm text-warning" role="alert">
              {message}
            </p>
          )}
        </div>
      </section>
    );
  }
  return (
    <>
      <section
        className={
          returning
            ? "space-y-4 rounded-[36px] border border-[var(--confirmation-border)] bg-[var(--confirmation-card)] p-5 sm:p-12"
            : "panel space-y-4 p-6"
        }
        aria-label="Subscription"
      >
        <h2 className="section-label [font:600_11px/1.5_ui-monospace,_monospace] tracking-[0.14em] uppercase text-body">
          Test subscription
        </h2>
        {returning && (
          <div role="status" aria-live="polite" className="space-y-2">
            <h3 className="text-lg font-semibold">
              {confirmation === "failed"
                ? "Checkout failed"
                : confirmation === "expired"
                  ? "Checkout expired"
                  : pollingEnded
                    ? "Confirmation timeout"
                    : "Confirming"}
            </h3>
            <p className="text-sm text-body">
              {confirmation === "failed"
                ? "The latest checkout or initial payment failed. Review Usage before trying again."
                : confirmation === "expired"
                  ? "The latest checkout or subscription expired. Review Usage before starting another checkout."
                  : pollingEnded
                    ? "Automatic checking has stopped after two minutes. Payment may still be processing. Refresh to check again or contact support."
                    : "Waiting for verified payment confirmation. We check every five seconds for up to two minutes. Your return from checkout does not confirm payment."}
            </p>
          </div>
        )}
        {!billing ? (
          <p className="text-sm text-body">Loading subscription status…</p>
        ) : (
          <>
            <p className="text-sm text-body">
              Current access:{" "}
              <strong className="text-foreground">
                {billing.isSuspended
                  ? "Suspended"
                  : billing.plan === "PAID"
                    ? "Paid"
                    : "Free"}
              </strong>{" "}
              · Subscription:{" "}
              {billing.status.toLowerCase().replaceAll("_", " ")}
            </p>
            {billing.isSuspended && (
              <p className="text-sm text-warning">
                Sending and paid features are suspended. Suspension does not
                cancel billing. You can still manage or cancel your subscription
                below.
              </p>
            )}
            {billing.hasOverride && (
              <p className="text-sm text-body">
                An active access override or grant affects your access
                separately from your subscription.
              </p>
            )}
            <p className="text-sm text-body">
              {billing.billingCountry === "IN"
                ? "Paid plan in India"
                : "Paid plan"}
              : <strong className="text-foreground">{publicPrice}</strong>.{" "}
              {PRICE_TAX_DESCRIPTION} Billing country determines eligibility;
              checkout shows the final quote.
            </p>
            {hasSubscription ? (
              <p className="text-sm text-body">
                Stored recurring amount before tax:{" "}
                <strong className="text-foreground">{recurring}</strong>.
                Checkout and invoices show applicable tax.
              </p>
            ) : billing.status !== "NONE" && (amount !== null || currency) ? (
              <details className="text-sm text-body">
                <summary className="min-h-11 cursor-pointer py-3 text-link">
                  Previous subscription
                </summary>
                <p className="mt-2">
                  Previous recurring amount before tax:{" "}
                  <strong className="text-foreground">{recurring}</strong>. This
                  is the stored amount for your previous subscription, not the
                  price of a new plan. It does not renew.
                </p>
              </details>
            ) : null}
            {pending && !returning && (
              <p className="text-sm text-body" role="status">
                Waiting for verified payment confirmation. Access updates
                automatically after confirmation; this can take several minutes.
              </p>
            )}
            {billing.cancellationPending && (
              <p className="text-sm text-body" role="status">
                Cancellation requested. Waiting for confirmation; your verified
                paid period is retained.
              </p>
            )}
            {billing.cancelAtPeriodEnd && billing.periodEnd && (
              <p className="text-sm text-body">
                Cancellation scheduled. Verified paid access ends{" "}
                <DateTime value={billing.periodEnd} />.
              </p>
            )}
            {billing.status === "PAST_DUE" && billing.gracePeriodEnd && (
              <p className="text-sm text-warning">
                Renewal payment needs attention. The verified grace period ends{" "}
                <DateTime value={billing.gracePeriodEnd} />.
              </p>
            )}
            {billing.status === "ACTIVE" &&
              !billing.cancelAtPeriodEnd &&
              billing.periodEnd && (
                <p className="text-sm text-body">
                  Next monthly renewal: <DateTime value={billing.periodEnd} />.
                  Verified paid period ends at this time.
                </p>
              )}
            <p className="text-sm text-body">
              {billing.mode === "test"
                ? "Test mode only. Use Dodo test payment details; no real charges are enabled."
                : billing.mode === "live"
                  ? "Dodo checkout shows the final amount before you pay. Live payments and renewals use real money."
                  : "Subscription checkout is unavailable until billing is configured."}
            </p>
            {!billing.configured ? (
              <p className="text-sm text-body">
                Checkout is not configured yet. Subscription controls are
                unavailable until configuration is restored; stored subscription
                details remain visible.
              </p>
            ) : (
              <>
                {!billing.checkoutEnabled && (
                  <p className="text-sm text-body">
                    Checkout is currently disabled.
                  </p>
                )}
                {billing.isSuspended ? (
                  <p className="text-sm text-body">
                    Upgrades are unavailable while suspended. Contact support
                    about account access.
                  </p>
                ) : (
                  !hasSubscription &&
                  !pending && (
                    <div className="space-y-3">
                      <p className="text-xs leading-5 text-body">
                        Enter your billing country in Dodo checkout. Review the
                        final price, currency, and applicable taxes before
                        paying.
                      </p>
                      <Button
                        type="button"
                        className="upgrade-shine relative isolate overflow-hidden"
                        aria-busy={busy}
                        disabled={busy || !billing.checkoutEnabled}
                        onClick={() => void open("checkout")}
                      >
                        {busy ? "Opening…" : "Upgrade to Premium"}
                      </Button>
                    </div>
                  )
                )}
                <div className="flex flex-wrap gap-3">
                  {!returning &&
                    hasSubscription &&
                    !billing.cancelAtPeriodEnd && (
                      <Button
                        type="button"
                        variant="outline"
                        disabled={busy || billing.cancellationPending}
                        onClick={() => void open("cancel")}
                      >
                        {billing.cancellationPending
                          ? "Cancellation pending"
                          : "Cancel at period end"}
                      </Button>
                    )}
                  {!returning && billing.hasCustomer && (
                    <Button
                      type="button"
                      variant="outline"
                      disabled={busy}
                      onClick={() => void open("portal")}
                    >
                      Manage subscription
                    </Button>
                  )}
                </div>
                {!returning && !billing.hasCustomer && (
                  <p className="text-sm text-body">
                    Manage is available after a billing account is created.
                  </p>
                )}
              </>
            )}
            <Link
              href="/pricing"
              className="flex min-h-11 w-fit items-center text-sm text-link underline"
            >
              Compare plan allowances
            </Link>
          </>
        )}
        <div className="flex flex-wrap items-center gap-4">
          <Button
            type="button"
            variant="outline"
            onClick={() => void manualRefresh.current()}
          >
            Refresh subscription status
          </Button>
          <a
            href={`mailto:${SUPPORT_EMAIL}`}
            className="inline-flex min-h-11 items-center text-sm text-link underline"
          >
            Contact support
          </a>
        </div>
        {lookupFailed && (
          <p className="text-sm text-warning" role="alert">
            Subscription status lookup temporarily failed. Your last verified
            status is retained. Try refreshing shortly.
          </p>
        )}
        {message && (
          <p className="text-sm text-warning" role="alert">
            {message}
          </p>
        )}
      </section>
      {returning && (
        <Link
          href="/usage"
          className="inline-flex min-h-11 items-center text-link underline"
        >
          Back to Usage
        </Link>
      )}
    </>
  );
}
